from npcs import *

# compact archetype constructor: npc(id, name, region, role, arch, sex, hair, hc, top, bot, shoes, pers, work, g, chat, ...)
A = npc
# ---------------- Aurelheim townsfolk ----------------
A("marta", "Marta Hale", "aurelheim", "innkeeper", "innkeeper", 1, 2, (150, 90, 50), (200, 150, 110), (110, 70, 50), (70, 50, 40), "Runs the Gilded Lantern with a ladle and an iron will.", (-12, 25),
  ["Room, meal, or both? Beds are clean, soup is hot, and I don't tolerate swords at the table.", "Heroes eat for free if they promise not to break anything. I haven't had a free hero yet. You're the first.", "Half the city's been through here this month. Everyone's got a story. Mine's soup.", "The Lantern's full every night. I'm adding a second floor. Don't ask where I got the lumber."],
  [("marta", "Guests tell me everything. Heroes tell me nothing. It's disappointing."), ("marta", "Last winter a man left a sword at the bar and never came back. It's on the wall. Want to see it?"), ("marta", "It hums when it rains.")], skin=0)
A("voll", "Sergeant Voll", "aurelheim", "trainer", "trainer", 0, 1, (110, 80, 60), (140, 60, 50), (70, 50, 40), (50, 40, 36), "A bellowing drill sergeant who mistakes affection for volume.", (-14, 12),
  ["Recruit! Posture! Guard up! Your elbows are a disgrace. Ten laps, then we talk swordplay.", "S-rank, huh? Doesn't excuse the elbows.", "I trained half the watch and every guard on that wall. Not one of them died of bad footwork.", "You never needed my training. I like to think it helped. Don't contradict me."],
  [("voll", "Rule one of swordplay: don't die. Rule two: don't die while looking silly."), ("voll", "Rule three: ask someone behind you to watch your back. They always say yes. Be worth it.")], trainer="sword_trials", skin=0)
A("corin", "Adept Corin", "aurelheim", "trainer", "trainer", 0, 0, (60, 40, 30), (70, 60, 130), (50, 40, 90), (40, 30, 60), "A nervous adept who explains everything three times and apologizes four.", (14, 14),
  ["Oh! Hello! Mana theory is... well, you probably don't... sorry. Sorry! Lessons are on hold until Dean Voss clears the east wing.", "A hero in the library! Everyone's whispering. I'm whispering. Do you hear me whispering?", "I've started giving lectures again. People attend. I'm shaking.", "Mana control is trust. Lyra taught me that. I think she'd say I'm doing well."],
  [("corin", "Spells are like sentences. You can't shout them at a wall."), ("corin", "Well. You can. But the wall doesn't understand.")], trainer="magic_trials", skin=0)
A("perpetua", "Sister Perpetua", "aurelheim", "trainer", "trainer", 1, 0, (220, 210, 200), (240, 235, 225), (225, 215, 195), (160, 140, 100), "A stern teacher of holy arts who believes compassion is a discipline.", (12, 20),
  ["Kneel if you must, but heal first. Prayers come after. The wounded can't wait for your poetry.", "I used to teach that the Tithe was a gift. I now teach that it was theft. I'm still angry.", "New students arrive daily. They want to heal the world. I teach them to heal one person without breaking themselves.", "The order is reborn. Thank you. I'll bake you something, and you'll eat it."],
  [("perpetua", "Healing is the oldest craft. Everyone does it badly the first time."), ("perpetua", "Do it again, anyway.")], trainer="holy_trials", skin=0)
A("tavish", "Old Tavish", "aurelheim", "trainer", "trainer", 0, 1, (200, 200, 200), (100, 100, 110), (70, 70, 80), (60, 60, 60), "A one-legged veteran who swears a shield is the finest weapon ever invented.", (-14, 16),
  ["Hah! A shield's not just a wall, lad. It's a promise made of wood. Learn to hold it and the sword will follow.", "Bram Ironvale. Aye, I know the name. Best shield-man in three generations. Tell him Tavish says he owes me a drink.", "Heard Bram's holding the line again. Warms an old man's leg.", "My leg may be gone but my stories aren't. Sit down."],
  [("tavish", "A shield-man's duty is to stand. Everyone else gets to be clever."), ("tavish", "We get the ugly, necessary work. We'd have it no other way.")], trainer="shield_trials", skin=0)
A("bao", "Bao the Cook", "aurelheim", "cook", "cook", 0, 3, (0, 0, 0), (240, 240, 235), (200, 200, 190), (80, 60, 50), "Feeds half of Aurelheim from one cart and refuses to share the recipe.", (-4, 28),
  ["Dumplings! Hot! Fresh! Three for a copper, five for a promise!", "Hero's special! You get extra pork. Don't tell the others.", "I cooked for the army. I'm cooking for the city. The pot never gets smaller; I do not know why.", "Lava-Fish Special? I'll make you a mild one. My stomach has limits."],
  [("bao", "People think great cooking is about spice. It's about timing."), ("bao", "A hero who eats on time wins more battles. Fact. I have a chart.")], shop="", skin=1)
A("wick", "Wick the Stable Master", "aurelheim", "stable", "stable", 0, 0, (130, 90, 50), (120, 90, 60), (70, 60, 50), (60, 50, 40), "Smells of hay, speaks to horses first and people second.", (4, 40),
  ["Mind the gray. He kicks. I mean that affectionately. Mostly.", "A mount for the desert, hero? The camels at Qasr Amun are the finest. Don't make eye contact. They know.", "Roads are safer. The horses are less nervous. So am I.", "I've named a foal after you. She's very fast and bites everyone. You'd get along."],
  [("wick", "A good mount learns your temper before you do."), ("wick", "Be kind to them. They remember.")], skin=0, night="tavern")
A("dorn", "Dorn the Angler", "aurelheim", "fisher", "fisher", 0, 1, (140, 110, 80), (80, 120, 110), (60, 80, 70), (60, 60, 50), "A fisherman who has been waiting for the same fish for eleven years.", (-18, 30),
  ["Shh. The big one's close. I can feel it in my knees.", "Fishing contest this Founders' Festival! Grand prize: a trophy shaped like a carp. I am a man of simple dreams.", "I caught it. It was smaller than I remembered. I let it go. It's mine in spirit.", "Fishing's still good. Better with the city quiet. Come sit."],
  [("dorn", "A hero's like a fish. Hard to catch, impossible to hold, delicious when you finally do."), ("dorn", "That was a joke. Please laugh.")], skin=0, night="tavern")
A("kestrel", "Kestrel", "aurelheim", "rival", "rival", 1, 0, (60, 50, 40), (60, 120, 170), (40, 70, 110), (40, 40, 50), "Leads Silverwing, a rival adventurer team, and assumes every rank is a race.", (-8, 8),
  ["Silverwing! Rank A, fifty-two bounties, zero failures. And you are? Oh. You. Right.", "We found out you're S-rank. Congratulations. We're going to beat your bounty record. Just so you know.", "Fine, you win. For now. We'll ride with you at the Gate. Don't make it weird.", "Silverwing is training the next generation of A-rankers. Do not tell them you beat us. They're optimistic."],
  [("kestrel", "Rank isn't everything. It's just the part they put on the board."), ("kestrel", "I'd still like to beat you. For the board.")], skin=0, night="tavern")
A("vane", "Vane", "aurelheim", "rival", "rival", 0, 0, (120, 130, 220), (100, 60, 150), (60, 40, 100), (40, 30, 60), "Silverwing's mage; flashy, sarcastic, secretly obsessed with Lyra's notes.", (-6, 8),
  ["Behold! The most dazzling mage in Aurelheim. Don't clap; it distracts the lightning.", "I heard you picked up Lyra Vesperine. Tell her I'm a huge fan. Don't tell her I said that.", "Her east wing! I attended the opening. I may have cried. It was the dust.", "I'm teaching a class. She guest-lectured. I fell off my chair."],
  [("vane", "Every mage wants raw power. I want style."), ("vane", "Lyra has both. It's infuriating.")], skin=0, night="tavern")
A("greta", "Greta Longstep", "aurelheim", "adventurer", "retired", 1, 2, (190, 190, 190), (110, 100, 80), (70, 60, 50), (60, 50, 40), "A retired adventurer who still sits facing the door.", (-10, 28),
  ["Sit down, child. Back to the wall, face to the door. Habit. I've outlived three parties and one marriage.", "You're the new S-rank. I was an A once. We didn't have S-rank then. We had 'lucky'.", "The war's close, I can feel it in my hip. Take my advice: pack socks.", "I'll knit your party something warm. It'll be hideous. It'll save your toes."],
  [("greta", "Every adventurer thinks the next dungeon will be the one that makes them rich. It makes someone rich. Rarely the adventurer."), ("greta", "Pick a good cook. Pick a good healer. The rest is details.")], skin=0, night="tavern")
A("ilse", "Ilse", "aurelheim", "herbalist", "herbalist", 1, 2, (110, 150, 80), (110, 150, 100), (90, 110, 80), (60, 70, 50), "A young herbalist with dirt under her nails and more patience than the guild board.", (6, 28),
  ["Fresh moonpetal! Dried frostcap! Ask me about the difference. No, really, ask. No one asks.", "Old Fenn taught me everything. He also taught me how to be quiet. I use the first lesson more.", "Selwyn's potions sell like hotcakes. Mine sell like hot, slightly-better-than-hotcakes.", "I started a garden on the north wall. It's mostly weeds. They're lovely weeds."],
  [("ilse", "Plants are loud once you learn how to listen."), ("ilse", "Moonpetal hums. Not a tune. A sort of... agreement.")], skin=0)
A("alden", "Guard Alden", "aurelheim", "guard", "guard", 0, 1, (130, 90, 60), (110, 120, 140), (80, 90, 110), (60, 60, 70), "A young guard trying very hard to look older than nineteen.", (-3, 36),
  ["Halt! Er. Welcome. I mean halt. State your business. Please. Sir.", "I was at the festival. I saw the light. I was too scared to run. I'm told that's bravery.", "Captain Dunmore says I've improved. She said it very quietly. I think I'm in trouble.", "I get to march with the army. First time outside the walls. Is it big? Everyone says it's big."],
  [("alden", "Sometimes a guard's job is standing very still while something scary happens."), ("alden", "I'm getting good at that part.")], skin=0, night="home")
A("verrin", "Lady Verrin", "aurelheim", "noble", "noble", 1, 2, (130, 70, 90), (160, 80, 110), (110, 50, 80), (80, 50, 70), "A noblewoman who delivers insults as compliments and compliments as threats.", (4, 14),
  ["How refreshing: a hero with a decent haircut. Do mind the mud on my carpet.", "Hanging out with a farmer's grandson is so... daring. I adore it. My mother is scandalized.", "The Archbishop at my table for years! I'm mortified. I'll donate to everything. Twice.", "Darius is doing well. I'd say I'm proud. I'd never tell him. We have an arrangement."],
  [("verrin", "Nobility is a performance for an audience that never leaves."), ("verrin", "Heroes at least get to stop for tea.")], skin=0, night="home")
A("penn", "Archivist Penn", "aurelheim", "scholar", "scholar", 0, 0, (120, 110, 100), (100, 90, 130), (70, 60, 100), (50, 40, 70), "An archivist who lowers his voice for every book and every secret.", (14, 12),
  ["Shh. The Archive sleeps. If you wake it, I'm sending you the bill.", "Pages are missing from the founding records. Not torn. Cut. Cleanly. Someone had a steady hand and a good reason.", "The Crown's memory is in my shelves now. I pretend not to be afraid.", "I've reopened the founding records. People can read the whole story. Most of them won't."],
  [("penn", "Every great hero in the archive dies in a footnote."), ("penn", "Except one. His page is just a title and a gap.")], skin=0, night="home")
A("tobin", "Tobin", "aurelheim", "apprentice", "apprentice", 0, 0, (150, 100, 60), (130, 110, 90), (80, 70, 60), (60, 50, 40), "Garrick's apprentice; eager, soot-streaked, and convinced every blade is a masterpiece.", (10, 28),
  ["Hi! Garrick says I can only touch the small hammers! I'm very good with the small hammers!", "Is it true you broke a sword by looking at it? I want to learn that.", "I forged a nail! A good one! Garrick said it was acceptable! I framed it!", "Master Garrick says I may touch the large hammers next year. I'm already wearing gloves."],
  [("tobin", "Garrick tells me to listen to the metal. I hear it clanging. Is that it?"), ("tobin", "Anyway. I'll listen harder.")], skin=0)
A("ash", "Brother Ash", "aurelheim", "defector", "cultist", 0, 3, (0, 0, 0), (90, 70, 120), (50, 40, 80), (30, 24, 40), "A hooded ex-cultist who flinches at bright lights and bright promises.", (-2, 38),
  ["...Oh. A hero. I'm not looking for trouble. I left. I left. Please don't tell them I was here.", "They say the hollow is merciful. It isn't. It's empty, and that isn't the same.", "The cult is falling apart. I wish I felt better about it.", "I'm teaching reading at the orphanage. It's the first thing I've done that nobody asked me to regret."],
  [("ash", "They told me the world was in pain and we could end it. They never said how many would have to stop first."), ("ash", "I'm still deciding if I deserve peace.")], skin=0, eye=(190, 120, 255), night="home")
A("odile", "Wanderer Odile", "aurelheim", "healer", "healer", 1, 2, (180, 140, 90), (200, 190, 140), (150, 130, 90), (110, 90, 60), "A traveling healer who treats everyone, charges whoever can pay, and sleeps in barns.", (10, 18),
  ["Wounds? Aches? Heartbreak? I cure two out of three. Guess which.", "A hero! Hold still, you have a bruise the shape of a country.", "I've healed more soldiers than I can count. Not one of them thanked me. I love that. It means they're alive.", "I'm opening a clinic. It'll have a bed for every pilgrim and a bucket for every opinion."],
  [("odile", "Healers carry something they don't talk about. We call it 'the weight'."), ("odile", "Mirelle carries more than most. Look after her.")], skin=0, night="tavern")
A("halbrook", "Merchant Halbrook", "aurelheim", "merchant", "merchant", 0, 0, (150, 120, 80), (130, 100, 60), (90, 70, 50), (70, 60, 50), "A round, cheerful peddler who sells everything and apologizes for nothing.", (-8, 28),
  ["Buy, sell, haggle! I stock everything but opinions. Those are free.", "Everyone wants a piece of the hero business. I sell little carved Kael dolls. They're mostly accurate.", "Trade routes are open! Prices drop! My wife says this is bad for business. She's wrong. I love it.", "Look, I've got a mural-print scarf from Khemet! No, you do not need it. Buy it."],
  [("halbrook", "A good deal leaves both parties thinking they've won."), ("halbrook", "A great deal leaves both parties thinking they've been robbed. That's the sweet spot.")], skin=0, night="tavern")
A("petra", "Petra the Florist", "aurelheim", "vendor", "vendor", 1, 0, (200, 130, 100), (200, 110, 140), (120, 70, 90), (100, 70, 60), "Sells flowers to soldiers, widows and the occasional hero with a lot to apologize for.", (2, 30),
  ["Flowers! Lilies for apologies, roses for confessions, daisies for everything else!", "A bouquet for your party? Colors tell the story. Let me guess: blue for loyalty, gold for hope.", "The war's close. Flowers sell better. I hate that. I sell them anyway.", "Tilly sends me seeds from the camp. They bloom in odd colors. I'm fond of odd."],
  [("petra", "Flowers don't fix things. They just say, 'I noticed.'"), ("petra", "That's often enough.")], skin=0)
# ---------------- Ashbrook ----------------
A("eldric", "Farmer Eldric", "ashbrook", "farmer", "farmer", 0, 1, (140, 120, 90), (140, 110, 80), (90, 80, 60), (70, 60, 50), "A weathered farmer who trusts weather and doesn't trust crystals.", (-8, 20),
  ["Harvest's late. If that crystal glows, you tell it I said hello. And that my back hurts.", "Ashes in the field. I'll replant. I always replant. Don't thank me for it, thank the dirt.", "We're rebuilding. The wheat will grow back before the walls do. Priorities.", "Ashbrook's loud again. Children, geese, bad singing. I'd forgotten I missed it."],
  [("eldric", "Soil forgives everything. Except neglect."), ("eldric", "You'd make a decent farmer. You should be one. Hmm. Nope. Hero's fine.")], stage="ash", skin=0)
A("bess", "Bess the Baker", "ashbrook", "cook", "cook", 1, 0, (190, 150, 110), (240, 235, 220), (200, 190, 170), (110, 90, 70), "Bakes at dawn, gossips at noon, forgives everything for a good loaf.", (-2, 22),
  ["Good morning, dear! Take a roll for the road. A ceremony day without breakfast is a bad omen.", "My ovens are gone. My hands are not. I'll bake over a campfire if I have to.", "We have a new oven! It's a little crooked. Like me. Come try it.", "Free bread for the hero who saved us. And for anyone who looks hungry. Which is everyone."],
  [("bess", "Bread is just patience in a crust."), ("bess", "Your grandfather used to steal the heels. I let him. Every time.")], stage="ash", skin=0)
A("rolf", "Young Rolf", "ashbrook", "child", "child", 0, 0, (150, 100, 60), (110, 130, 170), (70, 80, 110), (70, 60, 50), "A nine-year-old convinced he's going to be a hero, a pirate, and a baker.", (6, 24),
  ["Are you gonna get a sword? A big one? Can I touch it? Can I? Okay, just the handle!", "The bad things came and I hid in the barrel. Tilly says barrels are very brave. I'm gonna be brave next time.", "I practice with a stick! Tilly says it's a good stick! I named it Kael Jr.!", "Look, I'm taller! Sort of! Mostly my hair."],
  [("rolf", "Everybody says you're strong. Are you ever scared?"), ("rolf", "(Kael: 'Every day.') Whoa. That's... that's kind of cool actually.")], stage="ash", skin=0, scale=0.7)
A("wren", "Granny Wren", "ashbrook", "healer", "elder", 1, 2, (220, 220, 220), (150, 120, 150), (110, 90, 110), (80, 70, 80), "Ashbrook's healer, a sharp-eyed grandmother who has seen every fever twice.", (-6, 14),
  ["Stand still, boy. You're all elbows and nerves. Hold out your hand. Hm. Trembling. Healthy trembling.", "I stitched half the village after the fire. My needle's tired. I'm not.", "The camp's clinic is mine now. Don't let them tell you I'm retired.", "Your grandfather was stubborn as a rock and twice as quiet. I miss him. Visit the shrine."],
  [("wren", "A healer's work is mostly sitting with people."), ("wren", "The medicine's the excuse.")], stage="ash", skin=0)
# ---------------- Whisperwood ----------------
A("seren", "Monk Seren", "whisperwood", "monk", "monk", 1, 3, (0, 0, 0), (200, 150, 70), (150, 110, 50), (90, 70, 50), "A calm monk who speaks rarely and hits exactly once.", (0, 16),
  ["Be still. Listen. The forest is speaking, and you are interrupting.", "You come to learn focus? I do not teach. I wait until you are ready, and then I hit you.", "The trees are quieter. That is good. A forest at ease is a forest that forgets to worry.", "Tea? It is only water. But sit, and listen to it being water."],
  [("seren", "Focus is not squeezing. It is letting go of everything except the one thing."), ("seren", "Your grandfather knew. He taught me the pause before the strike.")], trainer="focus_strike", skin=0)
A("ravi", "Hunter Ravi", "whisperwood", "hunter", "hunter", 0, 1, (60, 40, 30), (80, 100, 60), (60, 70, 50), (60, 60, 50), "A tracker who says little and notices everything.", (-10, 20),
  ["Quiet. Something's moving in the ferns. Not an animal. Not a person. Something that wants to be both.", "The wolves have changed. Hungrier. Meaner. Not natural.", "The wolves are calming. A relief. I almost miss the challenge.", "A good hunt is just patience in boots."],
  [("ravi", "A wolf doesn't hate you. It just wants to eat. That's cleaner than most people."), ("ravi", "The 'wolf who wasn't'... I saw it. It looked at me like it was sorry.")], skin=0, night="tavern")
A("moss", "Ranger Moss", "whisperwood", "ranger", "ranger", 1, 0, (80, 120, 60), (90, 130, 80), (60, 90, 50), (60, 70, 50), "A cheerful ranger who names the trees and apologizes to them.", (6, 22),
  ["Hello, Oak! Hello, Pine! Hello, stranger! Please don't kick the roots. They're sensitive.", "Corruption's creeping from the Rootheart. I patrol the edge. I bring them tea. It doesn't help. It helps me.", "The trees are standing taller. I swear I heard one hum.", "I planted a sapling in your name. If it dies, it's the soil's fault."],
  [("moss", "I talk to trees because they never interrupt."), ("moss", "Except when they do. Then they just fall on you.")], skin=0)
# ---------------- Qasr Amun ----------------
A("sahar", "Sahar", "qasr_amun", "innkeeper", "innkeeper", 1, 2, (30, 20, 20), (180, 120, 50), (130, 90, 40), (90, 60, 40), "An innkeeper who measures guests by how they treat her lemonade.", (-8, 22),
  ["Water is free. Hospitality is not. Lemonade is a reasonable compromise.", "Everyone talks about you. I prefer to judge by how you handle my lemonade. Hm. Acceptable.", "The roads are open and the beds are full. I'm very tired and very happy.", "A room is always ready for you. And a lemonade. Without the sneer."],
  [("sahar", "A guest tells you who they are in the first five minutes. The rest is paperwork."), ("sahar", "You said thank you without being asked. Rare.")], skin=1)
A("jalil", "Jalil the Mount Master", "qasr_amun", "stable", "stable", 0, 1, (30, 24, 20), (140, 100, 60), (100, 70, 40), (70, 50, 40), "Breeds the finest sand-striders in the Sunscar and refuses to be hurried.", (4, 36),
  ["A mount is not a tool. It is a family member with opinions. Mine have strong ones.", "You earned the tribes' trust. A mount awaits you. Do not insult her by being nervous.", "The desert is easier on the riders now. The sand-striders appreciate it. They'd say so if they could.", "Come ride at dawn. The desert is a different creature then."],
  [("jalil", "The first rule of the desert: respect the water."), ("jalil", "The second rule: respect whoever's holding it.")], skin=1, night="tavern")
A("fatima", "Fatima the Weaver", "qasr_amun", "craft", "weaver", 1, 2, (50, 30, 30), (190, 80, 90), (130, 60, 70), (100, 60, 50), "Weaves stories into cloth and charges extra for the moral.", (-10, 26),
  ["Hold the thread, hero. Gently. It remembers the hands that held it.", "I'm weaving the story of the sands. The center is empty. A man with a golden aura, alone. I keep unpicking him.", "Every cloth I make has a rider in the corner now. A man with a sword and three friends. It looks right.", "The tapestry's finished. I'm hanging it in the council hall. Come see yourself in thread."],
  [("fatima", "Patterns lie. Threads don't."), ("fatima", "I wove the lone king three times and each time he came out lonelier.")], skin=1)
A("idris", "Scout Idris", "qasr_amun", "scout", "scout", 0, 3, (0, 0, 0), (150, 120, 80), (110, 90, 60), (80, 60, 50), "A desert scout who walks lightly, speaks softly, and counts everything twice.", (0, 38),
  ["Sand tells stories to those who watch it. Today it says: a storm, tomorrow afternoon. Pack accordingly.", "There are tracks near the catacombs. Large. Armored. Not human. I don't like it.", "The raiders are gone. I still look over my shoulder. I'll stop eventually.", "The dunes are quiet. Come walk with me. Bring water. And humility."],
  [("idris", "I can read a caravan's age by the depth of its wheel ruts."), ("idris", "I can read a person's lie by how fast they swallow. Don't swallow.")], skin=1)
A("nashu", "Excavator Nashu", "khemet_ruins", "excavator", "scholar", 0, 0, (30, 20, 20), (180, 150, 90), (130, 100, 60), (90, 70, 50), "Digs for old stones and talks to them in an old tongue.", (6, 10),
  ["Careful with that brush! It's older than your nation and probably more important.", "We found a new chamber! Mostly sand. And one broken pot. Still, the pot is fascinating.", "The Hourglass Vault is open. The sand there is... flowing in the right direction, finally. We're taking measurements.", "The ruins are mine to study forever. I've never been happier."],
  [("nashu", "History isn't dead. It's just very quiet."), ("nashu", "You have to dig for what it said.")], skin=1)
# ---------------- Hrimvald ----------------
A("gudrun", "Gudrun", "hrimvald", "innkeeper", "innkeeper", 1, 2, (200, 190, 150), (180, 140, 120), (130, 100, 80), (90, 70, 60), "A burly innkeeper who thinks stew solves everything and is usually right.", (-10, 22),
  ["Stew's hot, beds are warm, ale's cold. Don't ask me which is which. You'll find out.", "A hero in my inn! Free stew. Don't get used to it.", "The Choir's silence kept the guests away for weeks. Now I've got more than I can feed. Grand.", "Come back soon. I'll make you stew. It's the only thing I do. I do it well."],
  [("gudrun", "In the mountains, you learn two things. Keep your hands warm. Keep your friends warmer."), ("gudrun", "Hmm. That one is catchy. Write it down.")], skin=0)
A("halvar", "Bellwright Halvar", "hrimvald", "craft", "craft", 0, 1, (150, 150, 150), (130, 130, 150), (90, 90, 110), (70, 70, 90), "Casts the cathedral's bells and swears they sing different tunes each winter.", (6, 14),
  ["Bells aren't bronze. They're memory. Strike one and it tells you who rang it last.", "The big bell cracked in the Choir's silence. I'm recasting it. Hard work. Hard sorrow.", "The bell rings again. A clean note. I didn't know I missed it.", "I cast a small bell for your party. Hang it somewhere dignified. It'll hum when you're near."],
  [("halvar", "Isrevna used to tune the bells herself. They were perfect."), ("halvar", "Now they're only good.")], skin=0)
A("sigrid", "Guide Sigrid", "hrimvald", "guide", "guide", 1, 2, (190, 160, 100), (120, 150, 170), (80, 100, 130), (60, 70, 90), "A young guide who treats every mountain as a rival and every client as a friend.", (-6, 16),
  ["Let's climb! Not that one. That one's fussy. This one. This one loves us.", "Torvik taught me. He also taught me to be afraid of the Lighthouse. I'm planning a trip. Don't tell him.", "The mountain's friendlier. Almost chatty. I'll miss the danger, a little.", "Bring me along when you go back up. I'll carry the rope. And the snacks."],
  [("sigrid", "A climber's secret: every summit is just a long way of coming home."), ("sigrid", "Or a long way of finding out you shouldn't have left.")], skin=0, night="tavern")
# ---------------- Emberforge ----------------
A("cinda", "Cinda the Apprentice", "emberforge", "apprentice", "apprentice", 1, 0, (210, 100, 50), (150, 90, 60), (100, 70, 50), (60, 50, 40), "Brandt's apprentice; fearless around fire, terrified of mistakes.", (10, 24),
  ["Master Brandt says I'm not allowed to hit the forge with a sword. I say it's a test.", "Making the hero's sword? I'm helping! My job is to hold the thing. The thing is very hot. I'm brave.", "Brandt let me do the final polish! My hands shook. The edge held. He didn't say anything. He hugged me. It was awkward.", "I'm teaching others now. I tell them: don't be afraid of the fire. Be afraid of not asking."],
  [("cinda", "Forge-songs come from the hammer's rhythm. Each smith has their own."), ("cinda", "Mine's a bit off. Brandt says that's character.")], skin=0)
A("magnus", "Stoker Magnus", "emberforge", "miner", "stoker", 0, 1, (80, 60, 50), (100, 70, 60), (70, 50, 40), (50, 40, 36), "Feeds the city's furnaces with a growl and a surprisingly soft singing voice.", (-4, 20),
  ["Coal's low. Tempers are high. Want to help or want to talk?", "Volcano's grumbling. I can feel it in my teeth. I don't like it when my teeth have opinions.", "The eruption didn't hit. We lit candles anyway. Habit.", "Furnaces burn clean now. I hum while I shovel. Cinda says it's the first time she's heard me sing."],
  [("magnus", "A fire needs three things: fuel, air, and someone who cares."), ("magnus", "I'm the third one.")], skin=0, night="tavern")
A("vesna", "Vesna the Cook", "emberforge", "cook", "cook", 1, 2, (200, 80, 50), (230, 190, 160), (180, 140, 110), (100, 80, 60), "Serves Lava-Fish Special to anyone brave enough and regrets it with a laugh.", (-12, 26),
  ["Lava-Fish Special! It bites back! Ask for it mild if you've got a soft tongue.", "A hero! Try the Special! Come on! I'll put it on the house. And on your tongue.", "The fish were running thick this week. I'm swamped and delighted.", "A hero can only be as strong as his stomach. Eat, eat."],
  [("vesna", "I catch the fish myself. It's a spectator sport."), ("vesna", "Do not feed it to Magnus. He cries.")], skin=0, night="tavern")
A("doro", "Miner Doro", "emberforge", "miner", "miner", 0, 3, (0, 0, 0), (110, 100, 100), (80, 70, 70), (60, 50, 50), "A grizzled miner who knows every shaft by its smell.", (4, 18),
  ["The Ashen Mines go deeper than the maps do. Nobody likes to talk about the bottom.", "There's a song in the mines. Low. Like a blacksmith humming. It stops when you look for it.", "The mines are safe, the song's louder. Beautiful.", "I've started telling the young ones about the song. They say I'm daft. I say they'll hear it."],
  [("doro", "A lamp, a pick, and a loud voice. That's all a miner needs."), ("doro", "And a friend who'll dig you out.")], skin=0, night="tavern")
# ---------------- Front camp (Hollow Reach) ----------------
A("vale_d", "Deserter Vale", "front_camp", "deserter", "soldier", 0, 1, (90, 70, 60), (100, 90, 80), (70, 60, 50), (50, 40, 40), "A soldier who ran once and has been trying to forgive himself ever since.", (-10, 16),
  ["I ran. I admit it. When the first wave came I dropped my shield and fled. Shoot me or hire me.", "I wrote a letter to my daughter. I never sent it. Will you?", "I held the line this time. It was terrible. I'd do it again.", "I've been given a new shield. It's heavier than the old one. I'm learning to carry it."],
  [("vale_d", "You're not a coward because you run. You're a coward because you stop trying."), ("vale_d", "I'm trying.")], skin=0)
A("reyna", "Field Medic Reyna", "front_camp", "medic", "healer", 1, 0, (120, 90, 70), (240, 240, 235), (190, 180, 160), (130, 110, 90), "A field medic who sleeps in her boots and counts the living, not the dead.", (4, 18),
  ["Sit. Show me where it hurts. No, the real spot. Soldiers always lie about the real spot.", "Hollow sickness spreads fast. Hold your breath near the gate. I don't know if it helps. It makes me feel useful.", "We've lost fewer than expected. I keep counting. It still doesn't feel like enough.", "The medic tent's quiet. I'll never get used to that."],
  [("reyna", "The enemy doesn't scare me. Running out of bandages does."), ("reyna", "If you ever pass through here with spare linen, I will love you forever.")], skin=0)
